<script>
(function(){const track=document.getElementById('mobile-nav-track'),prev=document.getElementById('mobile-nav-prev'),next=document.getElementById('mobile-nav-next');if(track&&prev&&next){const step=156;const update=()=>{prev.disabled=track.scrollLeft<=3;next.disabled=track.scrollLeft+track.clientWidth>=track.scrollWidth-3};prev.addEventListener('click',()=>track.scrollBy({left:-step,behavior:'smooth'}));next.addEventListener('click',()=>track.scrollBy({left:step,behavior:'smooth'}));track.addEventListener('scroll',update,{passive:true});window.addEventListener('resize',update);const active=track.querySelector('a.active');if(active)requestAnimationFrame(()=>active.scrollIntoView({behavior:'instant',block:'nearest',inline:'center'}));update()}
const uploadUrl=@json(route('admin.documents.chunks'));const csrf=document.querySelector('meta[name="csrf-token"]')?.content||'';const CHUNK_SIZE=524288;document.addEventListener('DOMContentLoaded',function(){const input=document.querySelector('#upload-modal input[type="file"]');const form=input?.closest('form');if(!input||!form)return;const submit=form.querySelector('button.primary[type="submit"]');const progress=document.createElement('div');progress.style.cssText='display:none;margin-top:4px;padding:12px;border:1px solid rgba(104,204,235,.13);border-radius:12px;background:rgba(67,194,229,.05);font-size:12px;color:#86a5b4';progress.innerHTML='<div style="display:flex;justify-content:space-between"><span class="upload-status">Preparing upload…</span><strong class="upload-percent">0%</strong></div><div style="height:7px;margin-top:8px;border-radius:99px;background:rgba(255,255,255,.08);overflow:hidden"><span class="upload-bar" style="display:block;height:100%;width:0;border-radius:99px;background:linear-gradient(90deg,#229fd0,#54d4ee)"></span></div>';form.insertBefore(progress,form.querySelector('.modal-actions'));form.addEventListener('submit',async function(e){e.preventDefault();const file=input.files?.[0];if(!file)return;const folder=form.querySelector('input[name="folder_id"]')?.value||'';const status=progress.querySelector('.upload-status'),percent=progress.querySelector('.upload-percent'),bar=progress.querySelector('.upload-bar');progress.style.display='block';submit.disabled=true;input.disabled=true;try{const body=new URLSearchParams({filename:file.name,size:String(file.size),mime_type:file.type||'application/octet-stream'});if(folder)body.set('folder_id',folder);let r=await fetch(uploadUrl,{method:'POST',credentials:'same-origin',headers:{'X-CSRF-TOKEN':csrf,'X-Requested-With':'XMLHttpRequest','Accept':'application/json'},body});let p=await r.json().catch(()=>({}));if(!r.ok)throw Error(p.message||'Upload initialization failed.');const id=p.upload_id,size=Number(p.chunk_size)||CHUNK_SIZE,total=Math.ceil(file.size/size);for(let i=0;i<total;i++){const offset=i*size,blob=file.slice(offset,Math.min(offset+size,file.size));let ok=false;for(let a=1;a<=3&&!ok;a++){status.textContent=`Uploading chunk ${i+1} of ${total}…`;r=await fetch(uploadUrl,{method:'POST',credentials:'same-origin',headers:{'X-CSRF-TOKEN':csrf,'X-Requested-With':'XMLHttpRequest','Accept':'application/json','Content-Type':'application/octet-stream','X-Upload-Id':id,'X-Chunk-Index':String(i),'X-Chunk-Offset':String(offset)},body:blob});p=await r.json().catch(()=>({}));if(r.ok)ok=true;else if(a===3)throw Error(p.message||'Upload failed.');else await new Promise(x=>setTimeout(x,600*a))}const value=Math.round((Math.min(offset+blob.size,file.size)/file.size)*100);percent.textContent=value+'%';bar.style.width=value+'%'}status.textContent='Finalizing…';r=await fetch(uploadUrl+'?finalize=1',{method:'POST',credentials:'same-origin',headers:{'X-CSRF-TOKEN':csrf,'X-Requested-With':'XMLHttpRequest','Accept':'application/json','X-Upload-Id':id}});p=await r.json().catch(()=>({}));if(!r.ok)throw Error(p.message||'Finalization failed.');percent.textContent='100%';bar.style.width='100%';status.textContent='Upload complete.';setTimeout(()=>location.reload(),500)}catch(err){status.textContent=err.message||'Upload failed.';status.style.color='#ffb7b7';submit.disabled=false;input.disabled=false}})})})();
